"use strict";(self.webpackChunkreact_portfolio=self.webpackChunkreact_portfolio||[]).push([[7219],{7219:function(a){a.exports=JSON.parse('{"name":"Patrick Goodwin","menu":{"home":"Nyumbani","about":"Kuhusu Mimi","portfolio":"Kwingineko","projects":"Miradi ya Tovuti","tiger":"Lugha ya Tiger","portfolio_translator":"Portfolio Translator","formatter":"Muundo wa JSON & YAML","contact":"Wasiliana Nami"},"home":{"title":"Mhandisi Mwandamizi wa Rafu Kamili | Bidhaa na Mifumo","animated":{"first":"Mhandisi Mwandamizi wa Ratiba Kamili","second":"Mifumo na Mjenzi wa Usanifu","third":"Mhandisi wa Bidhaa wa SaaS","fourth":"Programu Inayoaminika, Matokeo ya Biashara"},"footer":"Tovuti sasa imetafsiriwa na inapatikana katika lugha 100+!","descriptionA":"Mhandisi mkuu kamili mwenye uzoefu wa miaka 6+ kuchukua bidhaa kutoka kwa mahitaji tata hadi mifumo ya uzalishaji inayotegemewa. Ninabuni usanifu nyuma ya programu za React, Angular, .NET, Node.js, Java, C#, Go, na SQL: mipaka ya huduma wazi, miundo ya kudumu ya data, mifumo salama ya ufikiaji na timu za njia za uwasilishaji zinaweza kufanya kazi kwa kujiamini.","descriptionB":"Kazi yangu inaunganisha maamuzi ya uhandisi na matokeo ya biashara. Kutoka kwa SaaS ya makadirio ya ujenzi ambayo hubadilisha data ya lahajedwali kuwa mapendekezo tayari kwa mteja hadi majukwaa ya wavuti ya kuzalisha mapato, ninaunda programu karibu na mtiririko wa kazi, hatari na. thamani inayopimika ambayo ni muhimu kwa watu wanaoitumia.","portfolio_button":"Kwingineko Yangu","contact_button":"Wasiliana Nami","about_button":"Kuhusu Mimi"},"about":{"title":"Kuhusu Mimi","personal_summary":{"title":"Muhtasari wa kibinafsi","text":"Mimi ni mhandisi mkuu kamili anayeishi Orlando, FL ambaye anamiliki njia kutoka kwa tatizo la bidhaa hadi matokeo ya uzalishaji. Mimi hufanya uchaguzi wa teknolojia katika huduma ya mfumo: .NET na Entity Framework Core wakati kikoa kilichoundwa kwa nguvu na jambo la kudumu linaloweza kujaribiwa; Angular au React wakati changamano mtiririko wa kazi unahitaji kiolesura kinachoweza kudumishwa; Node.js au Go wakati API, ujumuishaji, au zana ya utendakazi wa hali ya juu inahitaji muda mahususi wa utekelezaji. Katika bidhaa zote za SaaS, mtiririko wa kazi wa ndani, na majukwaa yanayowakabili wateja, ninaongoza kwa ubadilishanaji dhahiri, muundo salama na thabiti, majaribio ya kiotomatiki na mazoea ya utoaji ambayo kusaidia timu kusafirisha programu muhimu bila kuacha deni la uendeshaji nyuma."},"professional_experience":{"title":"Uzoefu wa Kitaalam","entries":[{"jobtitle":"Mhandisi Mwandamizi wa Programu","where":"Kubuni Interactive","date":"2025 - Sasa"},{"jobtitle":"Mhandisi wa Programu","where":"Bima ya Orion180","date":"2024 - 2025"},{"jobtitle":"Mhandisi wa Programu","where":"SupremeMC","date":"2020 - 2024"},{"jobtitle":"Mhandisi wa Programu","where":"Kuongeza kasi ya Kujifunza","date":"2023"},{"jobtitle":"Mhandisi Mkuu wa Programu (Programu ya Wanafunzi)","where":"Mpango wa GDI wa Chuo Kikuu cha Clemson","date":"2021 - 2022"},{"jobtitle":"Msimamizi wa Dawati","where":"Chuo Kikuu cha Clemson","date":"2021 - 2022"}]},"technical_skills":{"title":"Ujuzi wa Kiufundi","header1":"Lugha za Kupanga Programu","header2":"Mifumo na Maktaba","header3":"Zana na Teknolojia"},"services":{"title":"Huduma Zangu","entries":[{"title":"Uhandisi Kamili wa Stack","text":"Ninaongoza utoaji wa bidhaa kutoka mwisho hadi mwisho: kutafsiri mtiririko wa kazi wa biashara katika mipaka ya mfumo, miundo ya data, API na violesura, kisha kubeba kazi kupitia majaribio, usambazaji, na kurudia. Lengo ni programu ambayo timu inaweza kubadilika na kufanya kazi, si mkusanyiko wa skrini zilizokatwa."},{"title":"Usanifu wa Bidhaa na Jukwaa","text":"Ninachagua mifumo na muundo kulingana na tatizo: huduma za .NET za vikoa vya biashara, programu za Angular au React zinazoendeshwa na sehemu kwa ajili ya utendakazi changamano, uhusiano. miundo ya data ya mtiririko wa kazi unaowajibika, na miunganisho iliyoundwa na hali za kutofaulu, udhibiti wa ufikiaji na udumishaji akilini."},{"title":"Utoaji-Tayari wa Uzalishaji","text":"Ninaunda kwa kuzingatia hali halisi baada ya uzinduzi: siri zilizowekwa nje ya udhibiti wa chanzo, njia dhahiri za uhamishaji wa hifadhidata, uidhinishaji unaotegemea jukumu, uthibitishaji katika mipaka ya mfumo, majaribio ya kiotomatiki, ufahamu wa CI/CD, na uangalizi wa vitendo. Haya ni maelezo ambayo yanageuza mfano kuwa programu inayotegemewa."}]}},"portfolio":{"title":"Kwingineko","filter_by":"Chuja Kwingineko Kwa:","entries":{"biblioteca":{"title":"Biblioteca JSON","text":"Bomba la ujanibishaji la msingi wa Python ambalo hubadilisha chanzo kimoja cha maudhui kilichopangwa kuwa jalada linaloweza kufikiwa kimataifa. Hushughulikia data ya utafsiri kama mfumo unaoweza kudumishwa badala ya kunakili ukurasa unaorudiwa mwenyewe, ikiruhusu tovuti kueneza lugha 100+ na kufanya kufikia kimataifa. uwezo wa kufanya kazi badala ya kipengele cha wakati mmoja.","link":"https://github.com/pattygcoding/Biblioteca-JSON"},"connect_four":{"title":"Unganisha Nne","text":"Familia kubwa ya zaidi ya 50+ ya utekelezaji wa mchezo wa Unganisha Nne. Mradi huu unajumuisha utekelezaji katika zaidi ya lugha 30 tofauti za programu, ikiwa ni pamoja na Java, C++, Python, JavaScript, na zaidi. Zaidi ya hayo, pia inajumuisha zaidi ya mifumo 20+ tofauti au miundo mingine, ikijumuisha React.js, Ruby on Rails, ASP.NET, na zaidi.","link":"https://github.com/pattygcoding/Connect-Four-Language-Tree"},"grocery_app":{"title":"Programu ya mboga","text":"Programu kamili ya NET 9 Blazor Server inayoonyesha usanifu wa kimakusudi wa mandharinyuma kwa mtiririko wa kazi wa biashara. Mgawanyiko wa kidhibiti/huduma/ghala huweka sheria za programu, ufikiaji wa data, na uwasilishaji unaoweza kujaribiwa kwa kujitegemea; Msingi wa Mfumo wa Taasisi hutoa uendelevu wa kudumu; na kitengo cha majaribio cha kina hulinda tabia kadiri bidhaa inavyoendelea.","link":"https://github.com/pattygcoding/Grocery-App-Blazor"},"interop":{"title":"Mradi wa Interop","text":"Marejeleo ya mwingiliano wa lugha tofauti yanayochukua lugha 15 za upangaji na mifumo 18 ya utekelezaji. Mradi huchunguza mpaka ambapo mifumo mara nyingi huwa dhaifu: mikataba ya mchakato, ubadilishanaji wa data, tabia ya wakati wa utekelezaji, na njia za ujumuishaji zinazorudiwa. Inaonyesha fikra za mifumo inayohitajika wakati bidhaa ni kubwa kuliko rundo moja.","link":"https://github.com/pattygcoding/Interop-Samples"},"inventory_register":{"title":"Daftari la Mali","text":"POS yenye rundo kamili na mtiririko wa kazi wa orodha uliojengwa kwa Angular 17+ na Node.js. Ni mfano wa masuala ya uendeshaji wa mfumo wa B2B: watumiaji walioidhinishwa, udhibiti wa ufikiaji kulingana na jukumu, usahihi wa hesabu, na mtiririko wa malipo ya dhihaka. Mradi umeundwa kulingana na kazi halisi ambayo timu ya usajili hufanya, sio tu orodha ya vipengele vya mfumo.","link":"https://github.com/pattygcoding/Restaurant-Inventory-Register"},"formatter":{"title":"JSON & YAML Umbizo Otomatiki","text":"Chombo kinachotegemea kivinjari cha JSON na YAML cha uthibitishaji na uumbizaji kilichoundwa katika Go na kukusanywa kwa WebAssembly. Kuhamisha injini ya uchanganuzi kwenye WASM huweka mwingiliano kuwa wa mwitikio na wa ndani kwa kivinjari huku ukitumia kichanganuzi halisi kupata ingizo lisilo sahihi. Ni mfano mahususi wa kuchagua usanifu wa wakati wa utekelezaji kwa ajili ya utendaji, kubebeka na uaminifu wa mtumiaji.","link":"https://github.com/pattygcoding/JSON-YAML-Auto-Formatter"},"takeoff_engine":{"title":"Injini ya Kuruka","text":"Ujenzi wa kukadiria SaaS iliyojengwa karibu na mtiririko wa gharama kubwa, unaokabiliwa na makosa. Bidhaa ya React + Express humeza data ya CSV na Excel, huweka safu wima zisizothabiti katika muundo wa kikoa kinachoweza kutumika, hukokotoa uchimbaji wa mitaro na ujazo wa ardhi, kufuatilia kazi na markup, na hutoa mapendekezo ya PDF na Word yaliyo tayari kwa mteja. Huu ni uhandisi kamili wa mzunguko wa maisha ya bidhaa: uchanganuzi wa data, sheria za kukokotoa, mtiririko wa opereta ulioboreshwa, na bidhaa zinazoweza kuwasilishwa ambazo husaidia biashara kuhama kutoka kwa bidhaa ghafi hadi zabuni.","link":"https://takeoffengine.com"},"minecraft_json_generator":{"title":"Jenereta ya JSON ya Minecraft","text":"Jenereta nyepesi ya JSON iliyojengwa ndani ya Python kwa rasilimali ya Minecraft na pakiti za data. Mradi huu unatumika kutengeneza faili za JSON za mods za Minecraft, ikijumuisha vipengee maalum, vizuizi na huluki. Muhimu sana kwa sio tu kuunda hifadhidata maalum, lakini kwa mods pia kupitia kipengele cha kubadilisha jina la mod.","link":"https://github.com/pattygcoding/Minecraft-JSON-Generator"},"educational_experience":{"title":"Uzoefu Wangu wa Kielimu","text":"Kando na miradi yangu ya kibinafsi, pia nimepata ujuzi mwingi kutoka kwa uzoefu wa elimu. Bofya hapa kutazama wasifu wangu wa LinkedIn kwa habari zaidi.","link":"https://www.linkedin.com/in/patrickgoodwin7"},"professional_experience":{"title":"Uzoefu Wangu wa Kitaalam","text":"Miaka sita zaidi ya uzoefu wa kitaalamu wa uhandisi katika timu za bidhaa, majukwaa ya biashara na programu inayowalenga wateja. Kazi yangu imejumuisha kujenga safu za maombi zinazoweza kudumishwa, kushirikiana katika taaluma zote za uwasilishaji, na kufanya maamuzi ya kiufundi na mzunguko wa maisha wa bidhaa, kufanya kazi. hatari, na umiliki wa muda mrefu katika mtazamo.","link":"https://www.linkedin.com/in/patrickgoodwin7"},"portfolio_website":{"title":"Tovuti ya Patrick Goodwin Portfolio","text":"Kwingineko ya React inayozingatia uzalishaji ambayo inashughulikia ufikivu na ufikiaji wa kimataifa kama mahitaji ya kihandisi. Inajumuisha utafsiri unaoweza kudumishwa kwa lugha 100+, zana wasilianifu zinazoungwa mkono na WebAssembly, mifumo sikivu na inayofikika ya UI, na usanifu wa mradi. iliyoundwa kukua kama kazi mpya inasafirishwa.","link":"https://www.pattygcoding.com"},"lua_library":{"title":"Patrick\'s Lua Script Library","text":"Maktaba muhimu ya maandishi ya Lua kwa marejeleo ya siku zijazo. Maktaba hii inatumika kufanya kazi kiotomatiki katika hati za Lua, ambazo zinaweza kusaidia kwa kazi zinazohitaji utendakazi, kwani kwa kawaida Kilua ni lugha ya uandishi haraka kuliko Python na Ruby.","link":"https://github.com/pattygcoding/Lua-Scripts"},"excel_scripts":{"title":"Hati za Lahajedwali za Microsoft Excel za Patrick (VBA)","text":"Maktaba muhimu ya hati za VBA kwa Microsoft Excel. Maktaba hii inatumika kufanya kazi kiotomatiki katika lahajedwali za Excel.","link":"https://github.com/pattygcoding/Spreadsheet-Scripts"},"neovim_config":{"title":"Patrick\'s Neovim Config","text":"Usanidi wangu wa kibinafsi wa Neovim. Mradi huu unatumika kusanidi Neovim nipendavyo, ikijumuisha viambatanisho maalum vya funguo, mandhari, na programu-jalizi. Mradi huu unatumika kuifanya Neovim iwe rahisi zaidi kwa watumiaji na ufanisi kwa matumizi yangu ya kibinafsi.","link":"https://github.com/pattygcoding/Neovim-Config"},"python_maps":{"title":"Jenereta ya Ramani ya Patrick","text":"Zana ya kuripoti ya kijiografia ya Python iliyojengwa kwa GeoPandas na Matplotlib ili kutengeneza ramani za kaunti na jimbo la U.S. Hubadilisha data ya kijiografia kuwa vizalia vya uchanganuzi vinavyosomeka, ikionyesha mtazamo wa bomba la data: chagua maktaba sahihi za kikoa, kurekebisha pembejeo, na kutoa matokeo ambayo kuunga mkono maamuzi ya wazi.","link":"https://i.imgur.com/HxYLSXC.png"},"powershell_library":{"title":"Patrick\'s PowerShell Script Library","text":"Maktaba muhimu ya hati za PowerShell kwa marejeleo ya siku zijazo. Inatumika na kipengele cha hati ya wasifu, naona hii inasaidia sana kwa kazi za kiotomatiki kutoka kwa terminal ya Windows, kwani mimi ni mtumiaji wa mara kwa mara wa Windows OS.","link":"https://github.com/pattygcoding/Powershell-Scripts"},"ruby_library":{"title":"Maktaba ya Hati ya Ruby ya Patrick","text":"Maktaba muhimu ya maandishi ya Ruby kwa marejeleo ya siku zijazo. Inatumika kwa dhana za ukuzaji za Ruby kwenye reli za siku zijazo.","link":"https://github.com/pattygcoding/Ruby-Scripts"},"pdf_builder":{"title":"Mjenzi wa Ujuzi wa PDF","text":"Mtiririko wa kazi wa kutengeneza hati ulioundwa kwa Python, Pdfkit, Jinja2, HTML, na data iliyoundwa ya JSON. Inatenganisha data inayoweza kutumika tena kutoka kwa violezo vya uwasilishaji ili kutoa wasifu wa PDF uliobinafsishwa mara kwa mara, muundo wa vitendo wa kupunguza kazi ya mikono na kutengeneza hati za biashara. inayoweza kurudiwa.","link":"https://github.com/pattygcoding/PDFBuilderPublic"},"rijandel_encryption":{"title":"Mradi wa Usimbaji wa Rijandel","text":"Seti linganishi ya utekelezaji wa 10+ wa Rijndael katika vibadala 128-, 192- na 256-bit. Utekelezaji wa kanuni nyeti kwa usalama katika lugha zote ni zoezi la nidhamu katika vipimo mahususi, tabia inayoweza kujaribiwa, na vikomo vya uwezo wa kubebeka wa kiwango cha lugha, silika zote muhimu kwa mifumo inayoshughulikia data nyeti.","link":"https://github.com/pattygcoding/SupremeMC"},"suprememc":{"title":"Moduli ya SupremeMC Minecraft","text":"Mod ya Minecraft ambayo huongeza zana maalum, silaha, makundi, vitalu, vipimo na vipengele vingi zaidi kwenye mchezo. Imejengwa kwa matoleo ya Java 8-17 kwa matoleo yaliyochaguliwa ya Minecraft kati ya 1.16 na 1.20.","link":"https://www.curseforge.com/minecraft/mc-mods/suprememc"},"tiger_programming_language":{"title":"Lugha ya Kupanga Tiger","text":"Lugha maalum ya programu na mkalimani iliyoundwa katika Go ili kuchunguza muundo wa wakati wa utekelezaji wa lugha, tabia ya utekelezaji na utendakazi. Kuikusanya kwa WebAssembly na kuijumuisha kwenye kwingineko hutengeneza uso wa bidhaa halisi, unaoweza kuonekana kwa uhandisi wa kiwango cha mifumo badala ya kuacha kazi kama chombo. jaribio la hazina pekee.","link":"https://www.pattygcoding.com/tiger"},"tiger_tailgating_pros":{"title":"Tovuti ya Tiger Tailgating Pros","text":"Tovuti ya React iliyowasilishwa kwa biashara ya Clemson, SC ya kuweka mkia. Kazi inatafsiri toleo la biashara ndogo katika safari ya wazi ya mteja na uwepo wa wavuti unaotegemewa, kutumia mawazo ya bidhaa kusaidia shirika halisi kubadilisha riba. katika maswali na mapato.","link":"https://github.com/pattygcoding/TTProsBeta"},"turing_machine":{"title":"Mradi wa Mashine ya Turing","text":"Familia ya zaidi ya 30+ ya utekelezaji wa Mashine ya Kugeuza. Inatumika kuonyesha ukamilifu wa upangaji kwa lugha tofauti za upangaji kwa utafiti, haswa kwa Lugha ya Kupanga Tiger.","link":"https://github.com/pattygcoding/Turing-Machines"}}},"tiger_programming_language":{"title":"Lugha ya Kupanga Tiger"},"contact":{"title":"Wasiliana Nami","header":"Maelezo ya Mawasiliano","email":"pattygsocials@gmail.com","description":"Ninajibu maswali kutoka kwa barua pepe na ujumbe wa LinkedIn. Pia nitapiga simu tena ikiwa nambari yangu itatolewa kupitia wasifu au vinginevyo, ingawa ninapendelea kuweka nambari yangu ya simu kuwa ya faragha."},"formatter":{"title":"JSON & YAML Linter","description":"Zana ya ubora wa data inayotegemea kivinjari ambayo huidhinisha na kuunda JSON na YAML kwa kutumia injini ya Go iliyokusanywa kwa WebAssembly. Usanifu unaendelea kuchanganua karibu na mtumiaji kwa maoni ya haraka na ya faragha huku ukitekeleza sheria halisi za sintaksia kwenye mpaka wa data. Ni mfano thabiti wa kubuni utendakazi unaotegemewa wa msanidi programu kuhusu usahihi, utendakazi na uaminifu.","more_info1":"Kwa habari zaidi, rejelea README katika","more_info2":"Jalada la Umbizo la JSON/YAML.","format_as":"Umbizo Kama:","auto_detect":"Gundua Kiotomatiki","format":"Lint & Umbizo","valid_json":"\u2713 JSON halali","valid_yaml":"\u2713 YAML halali","invalid_json":"JSON batili","invalid_yaml":"YAML si sahihi","empty_input":"Tafadhali ingiza baadhi ya JSON au YAML ili kuunganisha.","too_large":"Ingizo ni kubwa mno (kiwango cha juu zaidi cha MB 1 kinaruhusiwa).","fixed_yaml_spacing":"\u26a0 YAML ilikuwa na nafasi/ujongezaji batili lakini imerekebishwa na kuumbizwa kiotomatiki.","loading":"Inapakia umbizo...","waiting_for_input":"Inasubiri ingizo...","load_failed":"Haijaweza kupakia kiumbizaji.","output":"Pato:","input_code":"Ingizo","json_examples":"Mifano ya JSON","yaml_examples":"Mifano ya YAML"},"tiger":{"title":"Lugha ya Tiger","description":"Tiger ni lugha maalum ya kupanga programu na mkalimani wa Go iliyoundwa ili kuchunguza usanifu wa wakati wa utekelezaji, semantiki za lugha na utendakazi. Kukusanya mkalimani kwa WebAssembly kunageuza mifumo kuwa bidhaa inayoingiliana, inayotegemea kivinjari: watumiaji wanaweza kutekeleza programu moja kwa moja huku muda wa utekelezaji ukiendelea kubebeka. na kutengwa na programu mwenyeji.","more_info1":"Kwa habari zaidi, rejelea README katika","more_info2":"Hazina ya GitHub ya Lugha ya Kupanga Lugha.","select_engine":"Chagua Injini:","tiger_code":"Msimbo wa Tiger:","run_tiger":"Kukimbia Tiger","output":"Pato:"},"tab":{"title":"Patrick Goodwin","description":"Mhandisi mkuu kamili mwenye uzoefu wa miaka 6+ katika kubuni bidhaa za SaaS, mifumo ya uzalishaji na programu ya kuzalisha mapato."},"copy":{"text":"Nakili","copied":"Imenakiliwa!"},"social_media":{"github":"GitHub","linkedin":"LinkedIn","youtube":"YouTube","text_strip":"Nifuate"},"languages":{"title":"Portfolio Translator","description":"Gundua jinsi jalada langu linavyoweza kufikiwa na wageni kutoka kote ulimwenguni kwa usaidizi wa zaidi ya lugha 100.","global_accessibility":{"title":"Ufikivu wa Kimataifa","description":"Kwingineko yangu inapatikana katika zaidi ya lugha {count}, hivyo kuifanya iweze kupatikana kwa wageni kutoka duniani kote. Mbinu hii ya lugha nyingi inaonyesha kujitolea kwangu kwa ujumuishi na kufikia kimataifa katika ukuzaji wa programu.","stats":{"languages_supported":"Lugha Zinazotumika","countries_represented":"Nchi zinazowakilishwa","continents_covered":"Mabara Yaliyofunikwa"}},"features":{"title":"Vipengele","items":[{"title":"Tafsiri ya Wakati Halisi:","description":"Badilisha lugha papo hapo na kiteuzi cha lugha"},{"title":"Lugha inayotokana na URL:","description":"Mapendeleo ya lugha yanahifadhiwa katika URL"},{"title":"Usaidizi wa Hati Asilia:","description":"Utoaji sahihi wa hati kama vile Kiarabu, Kichina, Kihindi, na zaidi"},{"title":"Unyeti wa Utamaduni:","description":"Tafsiri huzingatia muktadha wa kitamaduni, sio maana halisi tu"},{"title":"SEO Imeboreshwa:","description":"Kila lahaja ya lugha imeboreshwa kwa injini za utafutaji"}]},"world_map":{"title":"Ramani ya Dunia inayoingiliana","description":"Elea juu ya nchi kwenye ramani ili kuona lugha zinazotumika:","languages_label":"Lugha","legend":{"supported":"Lugha Zinazotumika","not_supported":"Hakuna Usaidizi wa Lugha"},"zoom_controls":{"zoom_in":"Kuza","zoom_out":"Zoom Out","reset":"Weka Mwonekano upya"}},"supported_languages":{"title":"Lugha Zinazotumika"},"interactive_country_map":{"title":"Ramani ya Nchi inayoingiliana","description":"Elea juu ya nchi hapa chini ili kuona lugha zinazotumika:","language_count":{"single":"lugha","multiple":"lugha"}},"tooltips":{"no_language_support":"Hakuna usaidizi wa lugha"}},"logotext":"PATRICK"}')}}]);